def _alternating(history):
    n = sum(1 for h in history if h["role"] == "assistant")
    return {"tool": "lookup_order", "args": {"order_id": "A-1" if n % 2 == 0 else "A-2"}}
def _obs(result):
    return [h["content"] for h in result["history"] if h["role"] == "tool"]
